export interface ExpressionRange {readonly start:number;readonly end:number}
export interface ExpressionCompletion {readonly id:string;readonly label:string;readonly detail?:string;readonly range:ExpressionRange;readonly insertText:string}
export interface ExpressionReference {readonly id:string;readonly label:string;readonly insertText:string;readonly detail?:string}
export interface ExpressionDiagnostic {readonly id:string;readonly severity:'error'|'warning'|'information';readonly message:string;readonly range:ExpressionRange}
export interface ExpressionQuery {readonly text:string;readonly selection:ExpressionRange;readonly references:readonly ExpressionReference[]}
export const EXPRESSION_MAX_LENGTH=65536;
const named=(s:string,max=512)=>typeof s==='string'&&s.trim().length>0&&s.length<=max;
export function validateExpressionText(text:string):void {if(typeof text!=='string'||text.length>EXPRESSION_MAX_LENGTH)throw new RangeError('Expression exceeds the text budget');}
/** Ranges use native UTF-16 offsets and must not split a surrogate pair. */
export function isExpressionBoundary(text:string,offset:number):boolean {return Number.isInteger(offset)&&offset>=0&&offset<=text.length&&!(offset>0&&offset<text.length&&text.charCodeAt(offset-1)>=0xd800&&text.charCodeAt(offset-1)<=0xdbff&&text.charCodeAt(offset)>=0xdc00&&text.charCodeAt(offset)<=0xdfff);}
export function validateExpressionRange(text:string,range:ExpressionRange):void {if(!range||!isExpressionBoundary(text,range.start)||!isExpressionBoundary(text,range.end)||range.start>range.end)throw new RangeError('Invalid expression UTF-16 range');}
export function replaceExpressionRange(text:string,range:ExpressionRange,insertText:string):{text:string;selection:ExpressionRange} {validateExpressionText(text);validateExpressionText(insertText);validateExpressionRange(text,range);const next=text.slice(0,range.start)+insertText+text.slice(range.end);validateExpressionText(next);const caret=range.start+insertText.length;return {text:next,selection:{start:caret,end:caret}};}
export function validateExpressionReferences(references:readonly ExpressionReference[]):void {if(references.length>10000||new Set(references.map(r=>r.id)).size!==references.length)throw new RangeError('Invalid expression reference budget or identities');for(const r of references){if(!named(r.id,256)||!named(r.label)||typeof r.insertText!=='string'||r.insertText.length>4096||r.detail!==undefined&&(typeof r.detail!=='string'||r.detail.length>4096))throw new TypeError('Invalid expression reference');}}
export function validateExpressionCompletions(text:string,items:readonly ExpressionCompletion[]):void {if(!Array.isArray(items)||items.length>128||new Set(items.map(i=>i.id)).size!==items.length)throw new RangeError('Invalid expression completion budget or identities');for(const i of items){if(!named(i.id,256)||!named(i.label)||typeof i.insertText!=='string'||i.insertText.length>4096||i.detail!==undefined&&(typeof i.detail!=='string'||i.detail.length>4096))throw new TypeError('Invalid expression completion');validateExpressionRange(text,i.range);replaceExpressionRange(text,i.range,i.insertText);}}
export function validateExpressionDiagnostics(text:string,items:readonly ExpressionDiagnostic[]):void {if(!Array.isArray(items)||items.length>1000||new Set(items.map(i=>i.id)).size!==items.length)throw new RangeError('Invalid expression diagnostic budget or identities');for(const i of items){if(!named(i.id,256)||!['error','warning','information'].includes(i.severity)||!named(i.message,4096))throw new TypeError('Invalid expression diagnostic');validateExpressionRange(text,i.range);}}
